  cardTitle: { fontFamily: "'Oswald', sans-serif", fontSize: 21, fontWeight: 600, letterSpacing: 0.5, margin: "0 0 10px", lineHeight: 1.15 },
  metaRow: { display: "flex", gap: 12, flexWrap: "wrap", fontSize: 12.5, opacity: 0.85, marginBottom: 10 },
